import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 12 章 数据与表格：清洗、分析与图表","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md"}'),o={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md"};function d(l,t,i,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 12 章 数据与表格：清洗、分析与图表（易懂版）](../../easy/第12章 数据与表格：清洗、分析与图表（易懂版）.md)</p></div><h1 id="第-12-章-数据与表格-清洗、分析与图表" tabindex="-1">第 12 章 数据与表格：清洗、分析与图表 <a class="header-anchor" href="#第-12-章-数据与表格-清洗、分析与图表" aria-label="Permalink to &quot;第 12 章 数据与表格：清洗、分析与图表&quot;">​</a></h1><blockquote><p>本章目标：掌握数据任务的四条铁律、清洗与分析的完整流程、让分析有说服力的方法，以及数据安全红线。<strong>数据任务的价值不在&quot;算得快&quot;，而在口径透明、过程可复核、结论有依据。</strong></p></blockquote><h2 id="_12-1-场景-数据是我的另一个主场" tabindex="-1">12.1 场景：数据是我的另一个主场 <a class="header-anchor" href="#_12-1-场景-数据是我的另一个主场" aria-label="Permalink to &quot;12.1 场景：数据是我的另一个主场&quot;">​</a></h2><p>数据类任务包括三大类：</p><table tabindex="0"><thead><tr><th>类别</th><th>说明</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>清洗</strong></td><td>去重、补缺、统一格式</td><td>合并多个 CSV、修正乱码</td></tr><tr><td><strong>分析</strong></td><td>汇总、对比、找趋势、找异常</td><td>月度销售汇总、渠道对比</td></tr><tr><td><strong>产出</strong></td><td>汇总表、图表、报告数据</td><td>生成汇总表、可视化脚本</td></tr></tbody></table><h2 id="_12-2-数据任务的四条铁律" tabindex="-1">12.2 数据任务的四条铁律 <a class="header-anchor" href="#_12-2-数据任务的四条铁律" aria-label="Permalink to &quot;12.2 数据任务的四条铁律&quot;">​</a></h2><h3 id="_12-2-1-铁律一-先看数据长什么样" tabindex="-1">12.2.1 铁律一：先看数据长什么样 <a class="header-anchor" href="#_12-2-1-铁律一-先看数据长什么样" aria-label="Permalink to &quot;12.2.1 铁律一：先看数据长什么样&quot;">​</a></h3><p><strong>绝不盲算。</strong> 拿到数据第一件事是看结构：字段、类型、样例行、缺失情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read 前几行 → 统计行数 → 检查缺失/重复 → 才谈分析</span></span></code></pre></div><p><strong>盲算的后果：</strong> 字段理解错了，后面全白算。先看 5 分钟数据，省下 5 小时返工。</p><h3 id="_12-2-2-铁律二-口径先对齐" tabindex="-1">12.2.2 铁律二：口径先对齐 <a class="header-anchor" href="#_12-2-2-铁律二-口径先对齐" aria-label="Permalink to &quot;12.2.2 铁律二：口径先对齐&quot;">​</a></h3><p>数据里的每个词都可能有多重含义：</p><table tabindex="0"><thead><tr><th>术语</th><th>可能的分歧</th></tr></thead><tbody><tr><td>&quot;销售额&quot;</td><td>含税/不含税？退款算不算？</td></tr><tr><td>&quot;活跃用户&quot;</td><td>登录算？还是下单算？</td></tr><tr><td>&quot;时间范围&quot;</td><td>自然月/滚动月？下单时间/支付时间？</td></tr></tbody></table><p><strong>先问清或先说明假设：</strong> &quot;我按&#39;不含税、扣除退款、自然月&#39;来算，可以吗？&quot;——口径写进文档，别人拿到你的汇总表也能看懂你是怎么算的。</p><h3 id="_12-2-3-铁律三-结果可复核" tabindex="-1">12.2.3 铁律三：结果可复核 <a class="header-anchor" href="#_12-2-3-铁律三-结果可复核" aria-label="Permalink to &quot;12.2.3 铁律三：结果可复核&quot;">​</a></h3><p><strong>给出可复现的脚本/步骤，你能自己再跑一遍。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产出 = 结果文件 + 处理脚本 + 口径说明</span></span></code></pre></div><p>数据结果如果不能复核，就等于没有结果。</p><h3 id="_12-2-4-铁律四-不编数" tabindex="-1">12.2.4 铁律四：不编数 <a class="header-anchor" href="#_12-2-4-铁律四-不编数" aria-label="Permalink to &quot;12.2.4 铁律四：不编数&quot;">​</a></h3><p><strong>缺失数据标&quot;缺失&quot;，绝不脑补。</strong> 编一个数字，整个分析的可信度归零。</p><h2 id="_12-3-案例-清洗并汇总一份销售数据" tabindex="-1">12.3 案例：清洗并汇总一份销售数据 <a class="header-anchor" href="#_12-3-案例-清洗并汇总一份销售数据" aria-label="Permalink to &quot;12.3 案例：清洗并汇总一份销售数据&quot;">​</a></h2><h3 id="_12-3-1-指令" tabindex="-1">12.3.1 指令 <a class="header-anchor" href="#_12-3-1-指令" aria-label="Permalink to &quot;12.3.1 指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/sales.csv 里有 3 个月的销售记录，帮我：</span></span>
<span class="line"><span>1. 去重（按订单号）、补全缺失的渠道字段（标 Unknown）</span></span>
<span class="line"><span>2. 按渠道+月份汇总销售额和订单量</span></span>
<span class="line"><span>3. 输出汇总表到 output/sales_summary.csv</span></span>
<span class="line"><span>4. 指出趋势和异常（比如某渠道某月暴跌）</span></span></code></pre></div><h3 id="_12-3-2-我的做法-逐步拆解" tabindex="-1">12.3.2 我的做法（逐步拆解） <a class="header-anchor" href="#_12-3-2-我的做法-逐步拆解" aria-label="Permalink to &quot;12.3.2 我的做法（逐步拆解）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Read 前几行 → 看字段结构（时间/订单号/渠道/金额...）</span></span>
<span class="line"><span>② 统计：总行数、重复行、缺失字段分布</span></span>
<span class="line"><span>③ 写清洗脚本：去重、补缺（Unknown）、统一日期格式</span></span>
<span class="line"><span>④ 输出中间结果 → 你抽查清洗质量</span></span>
<span class="line"><span>⑤ 汇总：按渠道+月份 group by → 输出 sales_summary.csv</span></span>
<span class="line"><span>⑥ 分析：环比/同比 → 标出异常点 → 写 3 条带数字依据的发现</span></span></code></pre></div><h3 id="_12-3-3-清洗-vs-分析的时间分配" tabindex="-1">12.3.3 清洗 vs 分析的时间分配 <a class="header-anchor" href="#_12-3-3-清洗-vs-分析的时间分配" aria-label="Permalink to &quot;12.3.3 清洗 vs 分析的时间分配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>耗时占比</th><th>原因</th></tr></thead><tbody><tr><td>清洗（去重/补缺/统一格式）</td><td>60%</td><td>脏数据是分析的隐形杀手</td></tr><tr><td>分析（汇总/对比/找异常）</td><td>30%</td><td>建立在干净数据之上</td></tr><tr><td>呈现（结论/建议）</td><td>10%</td><td>点睛之笔</td></tr></tbody></table><p><strong>别小看清洗</strong>——数据任务 80% 的问题都出在&quot;数据没洗干&quot;。</p><h2 id="_12-4-让分析更有说服力" tabindex="-1">12.4 让分析更有说服力 <a class="header-anchor" href="#_12-4-让分析更有说服力" aria-label="Permalink to &quot;12.4 让分析更有说服力&quot;">​</a></h2><p>数据给出后，我还会帮你做三件事：</p><h3 id="_12-4-1-找异常" tabindex="-1">12.4.1 找异常 <a class="header-anchor" href="#_12-4-1-找异常" aria-label="Permalink to &quot;12.4.1 找异常&quot;">​</a></h3><p>环比/同比变化超过阈值的地方：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;渠道 B 六月订单量 -32%，是全渠道唯一下降的。&quot;</span></span></code></pre></div><h3 id="_12-4-2-找归因线索" tabindex="-1">12.4.2 找归因线索 <a class="header-anchor" href="#_12-4-2-找归因线索" aria-label="Permalink to &quot;12.4.2 找归因线索&quot;">​</a></h3><p>异常和哪个维度相关？渠道？地区？时间？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;进一步看是华北区贡献了主要降幅，建议核实该区投放或库存情况。&quot;</span></span></code></pre></div><h3 id="_12-4-3-给中性建议" tabindex="-1">12.4.3 给中性建议 <a class="header-anchor" href="#_12-4-3-给中性建议" aria-label="Permalink to &quot;12.4.3 给中性建议&quot;">​</a></h3><p>基于数据给建议，不越权替你拍板：</p><table tabindex="0"><thead><tr><th>好的建议</th><th>差的建议</th></tr></thead><tbody><tr><td>&quot;渠道 A 连续 3 个月下降，建议排查投放素材&quot;</td><td>&quot;渠道 A 不行了&quot;</td></tr><tr><td>&quot;建议以数据为准调整预算，幅度你来定&quot;</td><td>&quot;把 A 的预算砍了&quot;</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">分析结论的写法公式</p><p><strong>数字 + 对象 + 对比基准 + 可能的归因方向</strong>： &quot;渠道 B（对象）订单量 -32%（数字），全渠道唯一下降（对比基准），可能和华北区投放有关（归因线索），建议核实（动作）。&quot;</p></div><h2 id="_12-5-图表的产出方式" tabindex="-1">12.5 图表的产出方式 <a class="header-anchor" href="#_12-5-图表的产出方式" aria-label="Permalink to &quot;12.5 图表的产出方式&quot;">​</a></h2><ul><li>我可以生成<strong>数据文件 + 绘图脚本</strong>（如 CSV + 绘图脚本）；</li><li>你可以本地运行脚本产出图表，或告诉我输出格式要求；</li><li><strong>图表要配读图结论</strong>：&quot;这张图说明了什么&quot;比图本身更重要。</li></ul><h3 id="_12-5-1-图表选择的建议" tabindex="-1">12.5.1 图表选择的建议 <a class="header-anchor" href="#_12-5-1-图表选择的建议" aria-label="Permalink to &quot;12.5.1 图表选择的建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>想表达什么</th><th>适合的图表</th></tr></thead><tbody><tr><td>趋势变化</td><td>折线图</td></tr><tr><td>占比构成</td><td>饼图/堆叠柱状图</td></tr><tr><td>对比排序</td><td>柱状图</td></tr><tr><td>相关性</td><td>散点图</td></tr></tbody></table><h2 id="_12-6-数据安全的红线" tabindex="-1">12.6 数据安全的红线 <a class="header-anchor" href="#_12-6-数据安全的红线" aria-label="Permalink to &quot;12.6 数据安全的红线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>红线</th><th>说明</th></tr></thead><tbody><tr><td>敏感数据授权</td><td>客户信息、财务明细 → 确认你授权我处理</td></tr><tr><td>结果不外泄</td><td>输出文件放在你指定的目录</td></tr><tr><td>口径透明</td><td>分析口径写进文档，别人看得懂</td></tr><tr><td>不存机密</td><td>数据里夹带的密钥/密码 → 明确提醒你</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">重点</p><p><strong>数据是敏感资源。</strong> 涉及客户信息、财务明细等敏感数据时：先确认授权、控制输出范围、不把原始数据写进记忆系统。</p></div><h2 id="_12-7-数据任务完整流程模板" tabindex="-1">12.7 数据任务完整流程模板 <a class="header-anchor" href="#_12-7-数据任务完整流程模板" aria-label="Permalink to &quot;12.7 数据任务完整流程模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 结构检查（字段/样例/缺失）</span></span>
<span class="line"><span>② 口径确认（怎么算，先对齐）</span></span>
<span class="line"><span>③ 清洗（去重/补缺/统一格式）→ 中间结果抽查</span></span>
<span class="line"><span>④ 分析（汇总/对比/异常）→ 输出数据文件</span></span>
<span class="line"><span>⑤ 结论（带数字依据的发现/建议）</span></span>
<span class="line"><span>⑥ 交付（结果 + 脚本 + 口径说明）</span></span></code></pre></div><h2 id="_12-8-练习" tabindex="-1">12.8 练习 <a class="header-anchor" href="#_12-8-练习" aria-label="Permalink to &quot;12.8 练习&quot;">​</a></h2><ol><li>给我一个真实数据文件，先做&quot;结构检查&quot;（字段、缺失、样例）；</li><li>让我按你的口径做一个汇总表，并抽查核对；</li><li>让我基于汇总表写出 3 条带数据依据的发现（用 12.4 的公式）；</li><li>复盘：这次数据任务里，口径对齐花了多久？值得吗？</li></ol><hr><blockquote><p>小结：数据任务的价值不在&quot;算得快&quot;，而在<strong>口径透明、过程可复核、结论有依据</strong>。四铁律（先看数据/口径对齐/结果可复核/不编数）+ 六步流程，就是数据协作的全部心法。下一章：知识管理。</p></blockquote>`,54)])])}const b=a(o,[["render",d]]);export{u as __pageData,b as default};
